def transform(grid):
    h, w = len(grid), len(grid[0])

    # The repeated row of nonzero cells specifies the colors and their order.
    palette = []
    best_run = 0
    for r in range(h):
        vals = [v for v in grid[r] if v]
        if not vals:
            continue
        run = 1
        while r + run < h and [v for v in grid[r + run] if v] == vals:
            run += 1
        if run > best_run:
            best_run, palette = run, vals

    if best_run < 2 or not palette:
        return grid

    # Find the shape component, using diagonal connectivity as well.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            components.append((color, cells))

    color, cells = max(components, key=lambda item: len(item[1]))
    if color not in palette:
        return grid

    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape_h = max(r for r, c in cells) - r0 + 1
    mask = [(r - r0, c - c0) for r, c in cells]

    # Keep the original copy aligned with its place in the palette sequence.
    start = r0 - palette.index(color) * shape_h
    out = [[0] * w for _ in range(h)]
    for i, new_color in enumerate(palette):
        for dr, dc in mask:
            rr, cc = start + i * shape_h + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = new_color
    return out

