    cols = [c for c in range(w) if c not in sep_cols]
    bg = Counter(grid[r][c] for r in rows for c in cols).most_common(1)[0][0]

    def groups(indices):
        out, group = [], []
        for i in indices:
            if group and i != group[-1] + 1:
                out.append(group)
                group = []
            group.append(i)
        if group:
            out.append(group)
