    return result

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Learn the repeating diagonal color sequence from the visible interior.
    samples = {}
    for r in range(3, h):
        for c in range(3, w):
            t = r + c
            if t >= 9 and grid[r][c] != 0:
                samples.setdefault(t, grid[r][c])

    period = 1
    for p in range(1, 16):
        residues = {}
        valid = True
        for t, color in samples.items():
            residue = t % p
            if residue in residues and residues[residue] != color:
                valid = False
                break
            residues[residue] = color
        if valid:
            period = p
            break

    sequence = {}
    for t, color in samples.items():
        sequence.setdefault(t % period, color)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                t = r + c
                out[r][c] = sequence.get(t % period, 1)
    return out

