    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]

    def bands(length, separators):
        result, start = [], 0
        for i in separators:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < length:
            result.append((start, length))
        return result

    row_bands = bands(h, sep_rows)
    col_bands = bands(w, sep_cols)

    counts = {}
    for row in grid:
        for value in row:
            if value != 3:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    patterns = {}
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    value = grid[r][c]
                    if value != background and value != 3:
                        patterns[(r - r0, c - c0)] = value

    out = [row[:] for row in grid]
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for (dr, dc), value in patterns.items():
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = value
    return out

