                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == bg and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not edge:
                for x, y in comp:
                    out[x][y] = 4
    return out

def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue

            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] == bg and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))

            r0 = min(x for x, y in cells)
            r1 = max(x for x, y in cells)
            c0 = min(y for x, y in cells)
            c1 = max(y for x, y in cells)

            # Only rectangular background regions qualify.
            if len(cells) != (r1 - r0 + 1) * (c1 - c0 + 1) or len(cells) < 3:
                continue

            # A region is a pocket when at least three sides are bounded
            # by the non-background color or by the grid boundary.
            sides = 0
            if r0 == 0 or all(grid[r0 - 1][y] != bg for y in range(c0, c1 + 1)):
                sides += 1
            if r1 == h - 1 or all(grid[r1 + 1][y] != bg for y in range(c0, c1 + 1)):
                sides += 1
            if c0 == 0 or all(grid[x][c0 - 1] != bg for x in range(r0, r1 + 1)):
                sides += 1
            if c1 == w - 1 or all(grid[x][c1 + 1] != bg for x in range(r0, r1 + 1)):
                sides += 1

            if sides >= 3:
                for x, y in cells:
                    out[x][y] = 4

    return out
